// Yapılandırma dosyasındaki her ürünü ayrı bir öğeye çevirir.
// Okuma zinciri hata verdiyse: dosya gerçekten YOKSA boş listeyle devam edilir,
// ama dosya bozuk/erişilemez ise çalışma durdurulur — aksi hâlde liste boş
// sanılıp üzerine yazılır ve veriler kaybolur.
const _dosyaKontrol = (okuNode, cikarNode, dosya) => {
  const okuHata = $(okuNode).first().json.error;
  const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
  if (/ENOENT|no such file|not found/i.test(okuMesaj)) return; // dosya henüz oluşmamış
  const cikarHata = $(cikarNode).first().json.error;
  if (okuHata || cikarHata) {
    const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
    throw new Error(dosya + ' okunamadı; veri kaybını önlemek için durduruldu → ' + m);
  }
};
_dosyaKontrol('Ürün Listesini Oku', 'Ürünleri Çıkar', 'fiyat-takibi.json');

const okunan = $input.first().json;
const u0 = (okunan.data && okunan.data.urunler) || [];
const urunler = Array.isArray(u0) ? u0 : [];
return urunler
  .filter((u) => u && String(u.url || '').startsWith('http'))
  .map((u, i) => ({
    json: {
      ad: String(u.ad || 'Ürün ' + (i + 1)),
      url: String(u.url),
      secici: String(u.secici || ''),
      esik: Number.isFinite(Number(u.esik)) && u.esik !== null && u.esik !== '' ? Number(u.esik) : null,
      sonFiyat: Number.isFinite(Number(u.sonFiyat)) && u.sonFiyat !== null ? Number(u.sonFiyat) : null,
    },
  }));

// İndirilen sayfadan çekilen metni sayıya çevirir (1.299,90 TL / 1,299.90 vb.).
const urun = $('Ürünleri Aç').item.json;
const hamDeger = $json.fiyatMetni;
const ham = (hamDeger === undefined || hamDeger === null) ? '' : String(hamDeger).trim();
let hata = '';
if ($json.error) hata = 'sayfa indirilemedi: ' + String(($json.error && $json.error.message) || $json.error).slice(0, 120);
else if (!ham) hata = 'fiyat metni bulunamadı (CSS seçiciyi kontrol edin)';

let fiyat = null;
if (ham) {
  const m = ham.replace(/\s+/g, ' ').match(/\d[\d.,]*/);
  if (m) {
    let s = m[0].replace(/[.,]$/, '');
    // "1.250" / "1,250" gibi yalnızca 3'lü gruplardan oluşanlar binlik ayraçtır.
    if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, '');
    else if (/^\d{1,3}(,\d{3})+$/.test(s)) s = s.replace(/,/g, '');
    else {
      const sonNokta = s.lastIndexOf('.');
      const sonVirgul = s.lastIndexOf(',');
      if (sonVirgul > sonNokta) s = s.replace(/\./g, '').replace(',', '.');
      else s = s.replace(/,/g, '');
    }
    const n = Number(s);
    if (Number.isFinite(n)) fiyat = n;
  }
  if (fiyat === null && !hata) hata = 'fiyat çözümlenemedi: "' + ham.slice(0, 60) + '"';
}

return { json: { ...urun, fiyat, hata } };

// Tüm ürün sonuçlarını birleştirir: dosya içeriğini günceller, uyarı metnini kurar.
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const sonuclar = $input.all().map((i) => i.json);
const simdi = new Date().toISOString();
const tl = (n) => Number(n).toLocaleString('tr-TR', { maximumFractionDigits: 2 }) + ' TL';

const urunler = sonuclar.map((s) => ({
  ad: s.ad,
  url: s.url,
  secici: s.secici,
  esik: s.esik,
  sonFiyat: s.fiyat !== null && s.fiyat !== undefined ? s.fiyat : (s.sonFiyat ?? null),
  sonKontrol: simdi,
  sonHata: s.hata || '',
}));

const dusenler = sonuclar.filter((s) => s.fiyat !== null && s.esik !== null && s.fiyat <= s.esik);
const degisenler = sonuclar.filter((s) => s.fiyat !== null && s.sonFiyat !== null && s.fiyat !== s.sonFiyat && !dusenler.includes(s));
const hatalilar = sonuclar.filter((s) => s.hata);

let html = '';
if (dusenler.length) {
  html += '<h3>🎯 Hedef fiyatın altında</h3><ul>' + dusenler
    .map((s) => '<li><a href="' + esc(s.url) + '">' + esc(s.ad) + '</a>: <b>' + tl(s.fiyat) + '</b> (hedef: ' + tl(s.esik) + ')</li>')
    .join('') + '</ul>';
}
if (degisenler.length) {
  html += '<h3>↕️ Fiyatı değişenler</h3><ul>' + degisenler
    .map((s) => '<li><a href="' + esc(s.url) + '">' + esc(s.ad) + '</a>: ' + tl(s.sonFiyat) + ' → <b>' + tl(s.fiyat) + '</b></li>')
    .join('') + '</ul>';
}
if (html && hatalilar.length) {
  html += '<p style="color:#999;font-size:12px">Kontrol edilemedi: ' + esc(hatalilar.map((s) => s.ad).join(', ')) + '</p>';
}

const bildirimVar = dusenler.length > 0 || degisenler.length > 0;
const konu = dusenler.length
  ? '[n8n] 🎯 ' + dusenler.length + ' ürün hedef fiyatın altında!'
  : '[n8n] 🏷 Fiyat değişikliği: ' + degisenler.map((s) => s.ad).join(', ').slice(0, 80);

return [{ json: { urunler, bildirimVar, konu, html: html ? '<div style="font-family:sans-serif;max-width:640px">' + html + '</div>' : '' } }];
